     "politica": "https://tiendademo.example.cl/politica-de-datos",
     "correo_datos": "datos@tiendademo.example.cl",
     "formulario": "https://tiendademo.example.cl/datos-personales",
     "plazo": "30 días hábiles"
   }}
]}
